import{_ as a,o as t,c as s,a5 as o}from"./chunks/framework.BEZBAInb.js";const h=JSON.parse('{"title":"Scene-based assets","description":"","frontmatter":{"title":"Scene-based assets","order":8},"headers":[],"relativePath":"en/latest/tutorial/core/scene-assets.md","filePath":"en/latest/tutorial/core/scene-assets.md","lastUpdated":1788455378000}'),n={name:"en/latest/tutorial/core/scene-assets.md"};function r(c,e,d,i,l,u){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="scene-based-assets" tabindex="-1">Scene-based assets <a class="header-anchor" href="#scene-based-assets" aria-label="Permalink to &quot;Scene-based assets&quot;">​</a></h1><p>Character and background entries now reference <code>PackedScene</code> resources. A scene may contain textures, video, Spine, Live2D, shaders, or custom nodes.</p><p>Character scenes should inherit <code>KonadoCharacterSceneBase</code> and override <code>_apply_status(resolved_status_name, original_status_name)</code>; scenes that can validate state names should also override <code>_has_status</code>. <code>_has_status</code> must be side-effect-free and idempotent because a delayed transition may query it when accepting the request and again at final commit. Scenes that safely expose pure textures may implement both <code>_get_current_status_transition_frame</code> and <code>_get_status_transition_frame</code> for a true premultiplied-alpha blend. Live2D, Spine, video, and custom scenes that cannot provide side-effect-free frames automatically use the safe fade-out/apply/fade-in path. Neither path duplicates the character scene. See <a href="./../script/actor/actor-change-state.html">Change Actor State</a> for configuration. Optional stage motion belongs in a <code>KonadoActorMotionLayer</code> scene whose <code>AnimationPlayer</code> animation names match KS motion names.</p><p>Each transition-frame call must return a newly created, independent frame; do not reuse and mutate the same frame for both endpoints.</p><p>Background scenes should inherit <code>KonadoBackgroundSceneBase</code>. Assign the scene to <code>background_scene</code>; add uniquely named <code>KonadoCameraMarker</code> nodes when camera commands are needed. These nodes only store target positions and zoom values; the dialogue template&#39;s camera renders the scene. Do not replace a custom rendering camera with <code>KonadoCameraMarker</code>. Built-in transitions are handled by <code>KonadoBackgroundTransitionLayer</code>. Transitions capture the complete scene through <code>SubViewport</code> by default. Select <code>DIRECT_TEXTURE</code> only when the rendered background is exactly equivalent to one unmodified source texture; backgrounds with layout, transforms, cameras, animation, materials, tinting, or multiple drawables must keep <code>VIEWPORT_CAPTURE</code>.</p><p>Configure the corresponding <code>character_scene</code> or <code>background_scene</code> in the resource list. Keep node paths stable and make scene roots fill their parent when they are UI-based.</p>',6)])])}const p=a(n,[["render",r]]);export{h as __pageData,p as default};
